/**
 * A dated record, in timeline form.
 *
 * The research was consistently against a dated feed, because an abandoned one
 * signals you have stopped. That risk is real and it is managed two ways here:
 * entries are a single line each and are generated by things that already
 * happen (a paper lands, a talk is given, a campaign runs), so nothing has to
 * be written for its own sake; and the list is seeded from the CV so it is
 * never thin.
 *
 * Every entry below is a fact from the CV. Nothing is invented.
 */

export type NewsKind = "appointment" | "paper" | "award" | "talk" | "field" | "programme";

export interface NewsItem {
  /** ISO date. Month precision is fine; day is used only where it is known. */
  date: string;
  kind: NewsKind;
  title: string;
  detail?: string;
  /** Internal or external link, when there is somewhere real to go. */
  href?: string;
}

export const kindLabel: Record<NewsKind, string> = {
  appointment: "Appointment",
  paper: "Paper",
  award: "Award",
  talk: "Talk",
  field: "Field campaign",
  programme: "Programme",
};

