/** Newest first, grouped by year for the timeline. */
export const newsByYear = () => {
  const groups = new Map<string, NewsItem[]>();
  for (const n of [...news].sort((a, b) => b.date.localeCompare(a.date))) {
    const y = n.date.slice(0, 4);
    if (!groups.has(y)) groups.set(y, []);
    groups.get(y)!.push(n);
  }
  return [...groups.entries()];
};

export const latestNews = (n = 4) =>
  [...news].sort((a, b) => b.date.localeCompare(a.date)).slice(0, n);
